CREATE TABLE farm_group (id VARCHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE);
ALTER TABLE worker ADD COLUMN group_id VARCHAR(36) NOT NULL DEFAULT '';
CREATE TABLE basket_type (id VARCHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, weight_kg DECIMAL(18,6) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE record_group (record_id VARCHAR(36) NOT NULL, group_id VARCHAR(36) NOT NULL, group_name VARCHAR(80) NOT NULL, inputs_json TEXT NOT NULL, PRIMARY KEY(record_id,group_id));
CREATE TABLE daily_signature (worker_id VARCHAR(36) NOT NULL, work_date DATE NOT NULL, fingerprint VARCHAR(64) NOT NULL, snapshot_json TEXT NOT NULL, signed_by VARCHAR(36) NOT NULL, signed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(worker_id,work_date));
CREATE TABLE print_template (id VARCHAR(36) PRIMARY KEY, template_json TEXT NOT NULL);
